import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"流转base64预览","description":"在 企业微信（政务微信） 的 ww.previewFile 方法中，url 参数必须是一个可通过网络访问的文件 URL，而不支持直接使用 Blob 数据。因此，不能直接用 Blob 数据作为参数来调用 previewFile。 如果后端只能返回文件流而非 URL，有几个可选的方案。","frontmatter":{"title":"流转base64预览","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"在 企业微信（政务微信） 的 ww.previewFile 方法中，url 参数必须是一个可通过网络访问的文件 URL，而不支持直接使用 Blob 数据。因此，不能直接用 Blob 数据作为参数来调用 previewFile。 如果后端只能返回文件流而非 URL，有几个可选的方案。","sidebarWeight":81,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/blob/快速了解/流转base64预览.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/流转base64预览.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/流转base64预览.md"}'),s={name:"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/流转base64预览.md"};function i(n,e,l,u,c,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="流转base64预览" tabindex="-1">流转base64预览 <a class="header-anchor" href="#流转base64预览" aria-label="Permalink to &quot;流转base64预览&quot;">​</a></h1><blockquote><p>本节目标：理解“流转base64预览”的核心思路，并能把它用于实际开发或面试表达。 在 <strong>企业微信（政务微信）</strong> 的 ww.previewFile 方法中，url 参数必须是一个可通过网络访问的文件 URL，而不支持直接使用 Blob 数据。因此，不能直接用 Blob 数据作为参数来调用 previewFile。 如果后端只能返回文件流而非 URL，有几个可选的方案： <strong>方案一：创建临时 URL 并上传到临时存储服务</strong> 如果你能够使用临时文件存储服务，可以将 Blob 数据上传到该服务并获取 URL。这样可以保持灵活性，但这个方案依赖于外部服务。 <strong>方案二：让后端返回一个文件下载地址</strong> 如果有权限修改后端，建议将文件下载地址作为 URL 返回，而不是直接返回流数据。这样可以避免前端再做处理，直接调用 previewFile 方法即可。 <strong>方案三：将 Blob 转换为 base64 并显示在 iframe 中</strong> 如果只是希望用户查看内容而不是下载文件，可以将 Blob 数据转换为 base64 格式，然后在页面中通过 iframe 或其他方式嵌入显示。这可以满足预览需求，但不适用于 ww.previewFile。 示例代码：</p></blockquote><p>javascript 复制代码 constexportCase= async(item) =&gt; { uni.request({ url: urlJoin( sxz.getConfig().api, <code>/sxz/checkRecord/getRecordFiles?id=${item.id}&amp;type=3</code>), header: { Authorization: uni.getStorageSync(&quot;token_type&quot;) + &quot; &quot;+ uni.getStorageSync(&quot;assess_token&quot;), }, method: &quot;GET&quot;, responseType: &quot;arraybuffer&quot;, success: (res) =&gt;{ if(res.statusCode=== 200) { constblob = newBlob([res.data], { type: &quot;application/vnd.ms-word&quot;}); constreader = newFileReader(); reader.onloadend= () =&gt;{ constbase64data = reader.result; constiframe = document.createElement(&quot;iframe&quot;); iframe.src= base64data; iframe.style.width= &quot;100%&quot;; iframe.style.height= &quot;100%&quot;; document.body.appendChild(iframe); }; reader.readAsDataURL(blob); } else{ uni.showToast({ title: &quot;获取文件失败&quot;, icon: &quot;none&quot;, }); } }, fail: (err) =&gt;{ console.error(&quot;网络请求失败&quot;, err); uni.showToast({ title: &quot;网络请求失败，请检查网络连接&quot;, icon: &quot;none&quot;, }); }, });}; 这种方式虽然不是调用 ww.previewFile，但适合用来实现文档或图片等内容的简单预览。</p></div>',1)])])}const q=t(s,[["render",i]]);export{b as __pageData,q as default};
